import { useEffect, useState } from "react";
import api from "../api";

function Feed() {
  /* ================= STATE ================= */
  const [posts, setPosts] = useState([]);
  const [filteredPosts, setFilteredPosts] = useState([]);

  // create post
  const [showCreatePost, setShowCreatePost] = useState(false);
  const [postType, setPostType] = useState("ARTICLE");
  const [content, setContent] = useState("");
  const [imageFile, setImageFile] = useState(null);

  // likes & comments
  const [likedPosts, setLikedPosts] = useState({});
  const [likeCounts, setLikeCounts] = useState({});
  const [commentCounts, setCommentCounts] = useState({});

  const [activePost, setActivePost] = useState(null);
  const [comments, setComments] = useState([]);
  const [commentText, setCommentText] = useState("");

  // TEMP (later from auth)
  const userId = 1;

  /* ================= FETCH FEED ================= */
  useEffect(() => {
    api.get("/feed").then((res) => {
      setPosts(res.data);
      setFilteredPosts(res.data);

      const likesMap = {};
      const commentsMap = {};

      res.data.forEach((post) => {
        api.get(`/post/${post.post_id}/likes/count`).then((r) => {
          likesMap[post.post_id] = r.data.count;
          setLikeCounts({ ...likesMap });
        });

        api.get(`/post/${post.post_id}/comments/count`).then((r) => {
          commentsMap[post.post_id] = r.data.count;
          setCommentCounts({ ...commentsMap });
        });
      });
    });
  }, []);

  /* ================= FILTER ================= */
  const showAll = () => setFilteredPosts(posts);
  const showImages = () =>
    setFilteredPosts(posts.filter((p) => p.image_url));
  const showArticles = () =>
    setFilteredPosts(posts.filter((p) => !p.image_url));

  /* ================= CREATE POST (FIXED LOGIC) ================= */
  const handleCreatePost = () => {
    if (postType === "ARTICLE" && !content.trim()) {
      return alert("Article content required");
    }

    if (postType === "IMAGE" && !imageFile) {
      return alert("Please add an image");
    }

    const formData = new FormData();

    // 🔥 FIX: map UI type → DB enum
    const dbPostType = postType === "IMAGE" ? "POST" : "ARTICLE";

    formData.append("post_type", dbPostType);
    formData.append("content", content);
    formData.append("created_by", userId);

    if (postType === "IMAGE") {
      formData.append("image", imageFile);
    }

    api.post("/post", formData).then(() => {
      setContent("");
      setImageFile(null);
      setPostType("ARTICLE");
      setShowCreatePost(false);
      window.location.reload();
    });
  };

  /* ================= LIKE ================= */
  const toggleLike = (postId) => {
    const isLiked = likedPosts[postId];

    const req = isLiked
      ? api.delete("/post/like", {
          data: { post_id: postId, user_id: userId },
        })
      : api.post("/post/like", {
          post_id: postId,
          user_id: userId,
        });

    req.then(() => {
      setLikedPosts({ ...likedPosts, [postId]: !isLiked });
      setLikeCounts({
        ...likeCounts,
        [postId]: isLiked
          ? likeCounts[postId] - 1
          : likeCounts[postId] + 1,
      });
    });
  };

  /* ================= COMMENTS ================= */
  const toggleComments = (postId) => {
    if (activePost === postId) {
      setActivePost(null);
      return;
    }

    api.get(`/post/${postId}/comments`).then((res) => {
      setComments(res.data);
      setActivePost(postId);
    });
  };

  const addComment = () => {
    if (!commentText.trim()) return;

    api.post("/post/comment", {
      post_id: activePost,
      user_id: userId,
      comment_text: commentText,
    }).then(() => {
      setCommentText("");
      setCommentCounts({
        ...commentCounts,
        [activePost]: commentCounts[activePost] + 1,
      });
      toggleComments(activePost);
    });
  };

  return (
    <div className="feed-layout">
      <aside className="feed-sidebar glass">
        <h3>Feed</h3>

        <button
          className="sidebar-btn"
          onClick={() => setShowCreatePost(!showCreatePost)}
        >
          ➕ Create Post
        </button>

        <button className="sidebar-btn" onClick={showAll}>All Posts</button>
        <button className="sidebar-btn" onClick={showImages}>Images</button>
        <button className="sidebar-btn" onClick={showArticles}>Articles</button>
      </aside>

      <main className="feed-main">
        <div className="feed-content">
          {/* CREATE POST UI (unchanged) */}
          {showCreatePost && (
            <div className="create-post glass">
              {/* post-type toggle, textarea, add image, post button */}
              {/* UI stays exactly as you already built */}
            </div>
          )}

          {/* POSTS */}
          {filteredPosts.map((post) => (
            <div key={post.post_id} className="post-card glass">
              <p>{post.content}</p>

              {post.image_url && (
                <img
                  src={`http://localhost:5000${post.image_url}`}
                  alt="post"
                />
              )}

              <div className="post-actions">
                <div onClick={() => toggleLike(post.post_id)}>
                  ❤️ {likeCounts[post.post_id] || 0}
                </div>
                <div onClick={() => toggleComments(post.post_id)}>
                  💬 {commentCounts[post.post_id] || 0}
                </div>
              </div>

              {activePost === post.post_id && (
                <div className="comment-box">
                  {comments.map((c, i) => (
                    <p key={i}>
                      <strong>{c.email}</strong>: {c.comment_text}
                    </p>
                  ))}
                  <input
                    value={commentText}
                    onChange={(e) => setCommentText(e.target.value)}
                  />
                  <button onClick={addComment}>Send</button>
                </div>
              )}
            </div>
          ))}
        </div>
      </main>
    </div>
  );
}

export default Feed;
